using System;
using System.IO;
using System.Reflection;
using System.Diagnostics;
using System.Windows.Forms;
using System.Runtime.InteropServices;
using Microsoft.Win32;
public static class Installation {
 const string UninstallKey="Software\\Microsoft\\Windows\\CurrentVersion\\Uninstall\\RockTekRemote";
 const string RunKey="Software\\Microsoft\\Windows\\CurrentVersion\\Run";
 const string Marker="RockTekRemote per-user v2";
 public static string Root(bool sandbox){return Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),sandbox?"RockTekRemote\\Sandbox":"Programs\\RockTekRemote");}
 static string Shortcut(bool sandbox){return sandbox?Path.Combine(Root(true),"RockTek Remote.lnk"):Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.Programs),"RockTek Remote.lnk");}
 static void SafeRoot(string root){string local=Path.GetFullPath(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData))+Path.DirectorySeparatorChar;if(!Path.GetFullPath(root).StartsWith(local,StringComparison.OrdinalIgnoreCase))throw new IOException("Unsafe install root");for(string p=root;p!=null&&p.Length>=local.Length;p=Path.GetDirectoryName(p))if(Directory.Exists(p)&&(File.GetAttributes(p)&FileAttributes.ReparsePoint)!=0)throw new IOException("Install path contains reparse point");}
 static void SafeFile(string p){if(File.Exists(p)&&(File.GetAttributes(p)&FileAttributes.ReparsePoint)!=0)throw new IOException("Owned file is a reparse point");}
 public static void Install(bool sandbox){string root=Root(sandbox);SafeRoot(root);string settings=sandbox?Path.Combine(root,"settings.json"):AppPaths.Settings(new string[0]);if(!sandbox){string warning;AppPaths.Settings(new string[0],out warning);if(!String.IsNullOrEmpty(warning))throw new IOException(warning);}FileSafety.CheckPath(settings);if(File.Exists(settings))RemoteConfig.Load(settings);Directory.CreateDirectory(root);string exe=Path.Combine(root,"RockTekRemote.exe"),marker=Path.Combine(root,"install.marker");if(File.Exists(exe)&&(!File.Exists(marker)||File.ReadAllText(marker)!=Marker))throw new IOException("Unowned existing executable; installation refused.");SafeFile(exe);FileSafety.CheckPath(marker);if(!sandbox)NativeBackSupport.Install();string temporary=exe+"."+Guid.NewGuid().ToString("N")+".new";try{using(Stream payload=Assembly.GetExecutingAssembly().GetManifestResourceStream("RockTekRemote.exe")){if(payload==null)throw new IOException("Embedded application missing");using(var output=new FileStream(temporary,FileMode.CreateNew,FileAccess.Write,FileShare.None))payload.CopyTo(output);}StopOwnedProcess(exe);if(File.Exists(exe))File.Replace(temporary,exe,null);else File.Move(temporary,exe);}finally{if(File.Exists(temporary))File.Delete(temporary);}FileSafety.CheckPath(marker);File.WriteAllText(marker,Marker);
 // Fresh restricted defaults require EXEs selected in the editor. Do not persist
 // invalid settings or silently make them global; first valid GUI Save creates JSON.
 string link=Shortcut(sandbox);SafeFile(link);Type type=Type.GetTypeFromProgID("WScript.Shell");object shell=Activator.CreateInstance(type),shortcut=null;try{shortcut=type.InvokeMember("CreateShortcut",BindingFlags.InvokeMethod,null,shell,new object[]{link});Type st=shortcut.GetType();st.InvokeMember("TargetPath",BindingFlags.SetProperty,null,shortcut,new object[]{exe});st.InvokeMember("Arguments",BindingFlags.SetProperty,null,shortcut,new object[]{sandbox?"--settings-only --config \""+settings+"\"":"--settings-only"});st.InvokeMember("WorkingDirectory",BindingFlags.SetProperty,null,shortcut,new object[]{root});st.InvokeMember("Description",BindingFlags.SetProperty,null,shortcut,new object[]{UiText.Get("RockTek Remote — настройки пульта")});st.InvokeMember("Save",BindingFlags.InvokeMethod,null,shortcut,null);}finally{if(shortcut!=null)Marshal.ReleaseComObject(shortcut);Marshal.ReleaseComObject(shell);}
 if(sandbox){File.WriteAllText(Path.Combine(root,"uninstall-entry.json"),"{\"DisplayName\":\"RockTek Remote\",\"DisplayVersion\":\"2.0\"}");return;}
 using(var k=Registry.CurrentUser.CreateSubKey(UninstallKey)){k.SetValue("DisplayName","RockTek Remote");k.SetValue("DisplayVersion","2.1.0");k.SetValue("Publisher","RockTek Remote");k.SetValue("InstallLocation",root);k.SetValue("DisplayIcon",exe);k.SetValue("UninstallString","\""+exe+"\" --uninstall");k.SetValue("QuietUninstallString","\""+exe+"\" --uninstall --silent");k.SetValue("NoModify",1,RegistryValueKind.DWord);k.SetValue("NoRepair",1,RegistryValueKind.DWord);}
 using(var k=Registry.CurrentUser.CreateSubKey(RunKey)){k.SetValue("RockTekRemote","\""+exe+"\"");}

 }
 [DllImport("kernel32.dll",SetLastError=true)] static extern IntPtr OpenProcess(uint access,bool inherit,int id);
 [DllImport("kernel32.dll",CharSet=CharSet.Unicode,SetLastError=true)] static extern bool QueryFullProcessImageName(IntPtr handle,uint flags,System.Text.StringBuilder path,ref uint size);
 [DllImport("kernel32.dll")] static extern bool CloseHandle(IntPtr handle);
 public static string ProcessPath(int id){IntPtr h=OpenProcess(0x1000,false,id);if(h==IntPtr.Zero)return null;try{var path=new System.Text.StringBuilder(32768);uint size=32768;return QueryFullProcessImageName(h,0,path,ref size)?path.ToString():null;}finally{CloseHandle(h);}}
 static void StopOwnedProcess(string exe){foreach(var p in Process.GetProcessesByName("RockTekRemote")){try{if(p.Id!=Process.GetCurrentProcess().Id&&String.Equals(ProcessPath(p.Id),exe,StringComparison.OrdinalIgnoreCase)){p.CloseMainWindow();if(!p.WaitForExit(1500)){p.Kill();if(!p.WaitForExit(3000))throw new IOException(UiText.Get("Не удалось завершить обработчик."));}}}finally{p.Dispose();}}}
 public static void Uninstall(string[] args){bool sandbox=Array.IndexOf(args,"--sandbox")>=0,silent=Array.IndexOf(args,"--silent")>=0;string root=Root(sandbox);SafeRoot(root);string exe=Path.Combine(root,"RockTekRemote.exe"),marker=Path.Combine(root,"install.marker");if(!String.Equals(Path.GetFullPath(Assembly.GetExecutingAssembly().Location),exe,StringComparison.OrdinalIgnoreCase))throw new IOException("Uninstall must run from the owned install directory");if(!File.Exists(marker)||File.ReadAllText(marker)!=Marker)throw new IOException("Installation ownership marker missing");if(!silent&&MessageBox.Show(UiText.Get("Удалить RockTek Remote? Настройки, OneDrive и выбранные приложения сохранятся."),"RockTek Remote",MessageBoxButtons.YesNo)!=DialogResult.Yes)return;
 // Only the exact installed process may be closed, never a portable copy.
 foreach(var p in Process.GetProcessesByName("RockTekRemote")){try{if(p.Id!=Process.GetCurrentProcess().Id&&String.Equals(ProcessPath(p.Id),exe,StringComparison.OrdinalIgnoreCase)){p.CloseMainWindow();if(!p.WaitForExit(1500)){p.Kill();p.WaitForExit(1500);}}}catch{}}
 if(!sandbox)NativeBackSupport.Uninstall();
 string link=Shortcut(sandbox);SafeFile(link);if(File.Exists(link))File.Delete(link);
 if(!sandbox){using(var k=Registry.CurrentUser.OpenSubKey(UninstallKey)){if(k!=null&&!String.Equals(Convert.ToString(k.GetValue("InstallLocation")),root,StringComparison.OrdinalIgnoreCase))throw new IOException("Uninstall registry ownership mismatch");}Registry.CurrentUser.DeleteSubKeyTree(UninstallKey,false);using(var k=Registry.CurrentUser.OpenSubKey(RunKey,true)){if(k!=null&&Convert.ToString(k.GetValue("RockTekRemote"))=="\""+exe+"\"")k.DeleteValue("RockTekRemote",false);}}
 else {string meta=Path.Combine(root,"uninstall-entry.json");SafeFile(meta);if(File.Exists(meta))File.Delete(meta);}
 SafeFile(marker);File.Delete(marker);SafeFile(exe);
 // No recursive delete; delayed helper removes exactly this locked EXE.
 string script=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"RockTekRemote","remove-"+Guid.NewGuid().ToString("N")+".ps1");Directory.CreateDirectory(Path.GetDirectoryName(script));string quoted=exe.Replace("'","''");File.WriteAllText(script,"$ErrorActionPreference='Stop';$p=Get-Process -Id "+Process.GetCurrentProcess().Id+" -ErrorAction SilentlyContinue;if($p){$p.WaitForExit()};for($i=0;$i -lt 20;$i++){try{if(Test-Path -LiteralPath '"+quoted+"'){Remove-Item -LiteralPath '"+quoted+"' -Force};break}catch{Start-Sleep -Milliseconds 250}};Remove-Item -LiteralPath $MyInvocation.MyCommand.Path -Force",new System.Text.UTF8Encoding(true));Process.Start(new ProcessStartInfo("powershell.exe","-NoProfile -ExecutionPolicy Bypass -File \""+script+"\""){UseShellExecute=false,CreateNoWindow=true});
 }
}
